using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using GrandWall.Api.IntegrationTests.Infrastructure;
namespace GrandWall.Api.IntegrationTests.ProductReturns;
public sealed class ReturnFinanceTests
{
 [Theory][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]
 public async Task EveryRoleCanCreateCustomer(int role)
 {using var factory=new GrandWallApiFactory();using var admin=factory.CreateClient();IntegrationTestAuthHelper.SetBearerToken(admin,await IntegrationTestAuthHelper.LoginAsync(admin,GrandWallApiFactory.AdminUsername,GrandWallApiFactory.AdminPassword));var username="customer."+Guid.NewGuid().ToString("N");(await admin.PostAsJsonAsync("/api/users",new{fullName="İşçi",username,password="EmployeeTest123!",role})).EnsureSuccessStatusCode();using var worker=factory.CreateClient();IntegrationTestAuthHelper.SetBearerToken(worker,await IntegrationTestAuthHelper.LoginAsync(worker,username,"EmployeeTest123!"));(await worker.PostAsJsonAsync("/api/customers",new{name="Yeni dükan",phoneNumber="",note=""})).EnsureSuccessStatusCode();}
 [Fact]public async Task ApprovalAppliesOnceAndKeepsPersonAccountManagerAndHyphenBatches()
 {using var factory=new GrandWallApiFactory();using var admin=factory.CreateClient();using var manager=factory.CreateClient();IntegrationTestAuthHelper.SetBearerToken(admin,await IntegrationTestAuthHelper.LoginAsync(admin,GrandWallApiFactory.AdminUsername,GrandWallApiFactory.AdminPassword));IntegrationTestAuthHelper.SetBearerToken(manager,await IntegrationTestAuthHelper.LoginAsManagerAsync(manager));
  var customerResponse=await admin.PostAsJsonAsync("/api/customers",new{name="Maliyyə dükanı",phoneNumber="",note=""});customerResponse.EnsureSuccessStatusCode();var customer=(await customerResponse.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
  var personResponse=await admin.PostAsJsonAsync("/api/return-persons",new{name="Babək",isActive=true});personResponse.EnsureSuccessStatusCode();var person=(await personResponse.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
  var warehouse=(await admin.GetFromJsonAsync<JsonElement>("/api/warehouses"))[0].GetProperty("id").GetGuid();
  var debtResponse=await admin.PostAsJsonAsync("/api/customer-accounts",new{customerId=customer,todayDebt=100,initialPreviousDebt=400});Assert.True(debtResponse.IsSuccessStatusCode,await debtResponse.Content.ReadAsStringAsync());
  (await admin.PostAsJsonAsync("/api/customer-accounts/settlements",new{operationId=Guid.NewGuid(),customerId=customer,cash=60,card=20,bonus=0})).EnsureSuccessStatusCode();
  var created=await admin.PostAsJsonAsync("/api/product-returns",new{customerId=customer,warehouseId=warehouse,amount=20,returnPersonId=person,items=new[]{new{productCode="510",batchNumber="611-1",quantity=1,productType=1},new{productCode="510",batchNumber="611",quantity=1,productType=1}}});created.EnsureSuccessStatusCode();var record=await created.Content.ReadFromJsonAsync<JsonElement>();var id=record.GetProperty("id").GetGuid();Assert.Equal("Babək",record.GetProperty("returnPersonName").GetString());Assert.Equal(2,record.GetProperty("items").GetArrayLength());
  var before=await admin.GetFromJsonAsync<JsonElement>($"/api/customer-accounts/{customer}");Assert.Equal(420,before.GetProperty("remainingDebt").GetDecimal());
  var uploadId=Guid.NewGuid();
  async Task<JsonElement> Upload(){using var content=new MultipartFormDataContent();var bytes=new ByteArrayContent(new byte[]{1,2,3,4});bytes.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue("image/jpeg");content.Add(bytes,"file","proof.jpg");content.Add(new StringContent(uploadId.ToString()),"operationId");var response=await admin.PostAsync($"/api/product-returns/{id}/photos",content);response.EnsureSuccessStatusCode();return await response.Content.ReadFromJsonAsync<JsonElement>();}
  var photo=await Upload();var retriedPhoto=await Upload();Assert.Equal(photo.GetProperty("id").GetGuid(),retriedPhoto.GetProperty("id").GetGuid());record=await admin.GetFromJsonAsync<JsonElement>($"/api/product-returns/{id}");Assert.Single(record.GetProperty("photos").EnumerateArray());
  (await admin.PostAsync($"/api/product-returns/{id}/submit",null)).EnsureSuccessStatusCode();(await manager.PostAsJsonAsync($"/api/product-returns/{id}/complete",new{note=""})).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Conflict,(await manager.PostAsJsonAsync($"/api/product-returns/{id}/complete",new{note=""})).StatusCode);
  var after=await admin.GetFromJsonAsync<JsonElement>($"/api/customer-accounts/{customer}");Assert.Equal(400,after.GetProperty("remainingDebt").GetDecimal());Assert.Equal(80,after.GetProperty("totalPaid").GetDecimal());record=await manager.GetFromJsonAsync<JsonElement>($"/api/product-returns/{id}");Assert.NotEqual(record.GetProperty("createdByUserId").GetGuid(),record.GetProperty("processedByUserId").GetGuid());
  var cancelled=await admin.PostAsJsonAsync("/api/product-returns",new{customerId=customer,warehouseId=warehouse,amount=20,returnPersonId=person,items=new[]{new{productCode="20",batchNumber="510-611-1",quantity=1,productType=1}}});cancelled.EnsureSuccessStatusCode();var cancelledId=(await cancelled.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();(await manager.PostAsJsonAsync($"/api/product-returns/{cancelledId}/cancel",new{note="Rədd edildi"})).EnsureSuccessStatusCode();after=await admin.GetFromJsonAsync<JsonElement>($"/api/customer-accounts/{customer}");Assert.Equal(400,after.GetProperty("remainingDebt").GetDecimal());
 }
}
